SET NOCOUNT ON;SET XACT_ABORT ON;BEGIN TRANSACTION;
IF OBJECT_ID('dbo.DisputeCases','U') IS NULL
BEGIN
 CREATE TABLE dbo.DisputeCases(Id UNIQUEIDENTIFIER NOT NULL,ParticipationId UNIQUEIDENTIFIER NOT NULL,CreatedByUserId UNIQUEIDENTIFIER NOT NULL,AssignedAdminUserId UNIQUEIDENTIFIER NULL,Category NVARCHAR(30) NOT NULL,Subject NVARCHAR(200) NOT NULL,Description NVARCHAR(2000) NOT NULL,Status NVARCHAR(30) NOT NULL,Priority NVARCHAR(20) NOT NULL,IsActive BIT NOT NULL,ResolutionNote NVARCHAR(2000) NULL,CreatedAtUtc DATETIME2(7) NOT NULL,UpdatedAtUtc DATETIME2(7) NULL,ResolvedAtUtc DATETIME2(7) NULL,CONSTRAINT PK_DisputeCases PRIMARY KEY(Id),CONSTRAINT FK_DisputeCases_Participation FOREIGN KEY(ParticipationId) REFERENCES dbo.Participations(Id),CONSTRAINT FK_DisputeCases_Creator FOREIGN KEY(CreatedByUserId) REFERENCES dbo.Users(Id),CONSTRAINT FK_DisputeCases_Admin FOREIGN KEY(AssignedAdminUserId) REFERENCES dbo.Users(Id),CONSTRAINT CK_DisputeCases_Category CHECK(Category IN('Booking','Shipment','Deliverable','Payment','Review','Other')),CONSTRAINT CK_DisputeCases_Status CHECK(Status IN('Open','InReview','Resolved','Rejected','Cancelled')),CONSTRAINT CK_DisputeCases_Priority CHECK(Priority IN('Normal','High')),CONSTRAINT CK_DisputeCases_Active CHECK((Status IN('Open','InReview') AND IsActive=1) OR (Status IN('Resolved','Rejected','Cancelled') AND IsActive=0)));
 CREATE UNIQUE INDEX UX_DisputeCases_Active_Participation_Category ON dbo.DisputeCases(ParticipationId,Category,IsActive) WHERE IsActive=1;
 CREATE INDEX IX_DisputeCases_Status_Priority_Created ON dbo.DisputeCases(Status,Priority,CreatedAtUtc DESC);
END;
IF OBJECT_ID('dbo.DisputeCaseStatusHistories','U') IS NULL
BEGIN
 CREATE TABLE dbo.DisputeCaseStatusHistories(Id UNIQUEIDENTIFIER NOT NULL,DisputeCaseId UNIQUEIDENTIFIER NOT NULL,FromStatus NVARCHAR(30) NULL,ToStatus NVARCHAR(30) NOT NULL,Note NVARCHAR(2000) NULL,ActorUserId UNIQUEIDENTIFIER NULL,CreatedAtUtc DATETIME2(7) NOT NULL,CONSTRAINT PK_DisputeCaseStatusHistories PRIMARY KEY(Id),CONSTRAINT FK_DisputeCaseStatusHistories_Case FOREIGN KEY(DisputeCaseId) REFERENCES dbo.DisputeCases(Id),CONSTRAINT FK_DisputeCaseStatusHistories_Actor FOREIGN KEY(ActorUserId) REFERENCES dbo.Users(Id),CONSTRAINT CK_DisputeCaseStatusHistories_From CHECK(FromStatus IS NULL OR FromStatus IN('Open','InReview','Resolved','Rejected','Cancelled')),CONSTRAINT CK_DisputeCaseStatusHistories_To CHECK(ToStatus IN('Open','InReview','Resolved','Rejected','Cancelled')));
 CREATE INDEX IX_DisputeCaseStatusHistories_Case_Created ON dbo.DisputeCaseStatusHistories(DisputeCaseId,CreatedAtUtc);
END;
EXEC(N'CREATE OR ALTER TRIGGER dbo.TR_DisputeCaseStatusHistories_AppendOnly ON dbo.DisputeCaseStatusHistories INSTEAD OF UPDATE, DELETE AS BEGIN THROW 51035, ''DisputeCaseStatusHistories is append-only.'', 1; END;');
IF NOT EXISTS(SELECT 1 FROM dbo.Menus WHERE Code='MENU_ADMIN_DISPUTES') INSERT INTO dbo.Menus(Id,Code,Title,Path,Icon,ParentId,OrderNo,IsVisible,CreatedAtUtc)VALUES(NEWID(),'MENU_ADMIN_DISPUTES',N'Tranh chấp','/Admin/Disputes','fa-solid fa-scale-balanced',NULL,8,1,SYSUTCDATETIME());
IF NOT EXISTS(SELECT 1 FROM dbo.Menus WHERE Code='MENU_BRAND_DISPUTES') INSERT INTO dbo.Menus(Id,Code,Title,Path,Icon,ParentId,OrderNo,IsVisible,CreatedAtUtc)VALUES(NEWID(),'MENU_BRAND_DISPUTES',N'Tranh chấp','/Brand/Disputes','fa-solid fa-life-ring',NULL,7,1,SYSUTCDATETIME());
IF NOT EXISTS(SELECT 1 FROM dbo.Menus WHERE Code='MENU_KOC_DISPUTES') INSERT INTO dbo.Menus(Id,Code,Title,Path,Icon,ParentId,OrderNo,IsVisible,CreatedAtUtc)VALUES(NEWID(),'MENU_KOC_DISPUTES',N'Tranh chấp','/Koc/Disputes','fa-solid fa-life-ring',NULL,7,1,SYSUTCDATETIME());
DECLARE @Admin UNIQUEIDENTIFIER=(SELECT TOP 1 Id FROM dbo.Roles WHERE UPPER(Code)='ADMIN'),@Brand UNIQUEIDENTIFIER=(SELECT TOP 1 Id FROM dbo.Roles WHERE UPPER(Code)='BRAND'),@Koc UNIQUEIDENTIFIER=(SELECT TOP 1 Id FROM dbo.Roles WHERE UPPER(Code)='KOC');
INSERT INTO dbo.RoleMenus(RoleId,MenuId,CreatedAtUtc) SELECT v.RoleId,m.Id,SYSUTCDATETIME() FROM(VALUES(@Admin,'MENU_ADMIN_DISPUTES'),(@Brand,'MENU_BRAND_DISPUTES'),(@Koc,'MENU_KOC_DISPUTES'))v(RoleId,Code) JOIN dbo.Menus m ON m.Code=v.Code WHERE v.RoleId IS NOT NULL AND NOT EXISTS(SELECT 1 FROM dbo.RoleMenus rm WHERE rm.RoleId=v.RoleId AND rm.MenuId=m.Id);
COMMIT TRANSACTION;
